/** Each test receives independent immutable-origin database bytes. */
export function canonicalAdoption40DatabaseBytes(): Uint8Array {
  const bytes = gunzipSync(Buffer.from(canonicalAdoption40GzipBase64, "base64"), {
    maxOutputLength: canonicalAdoption40Fixture.databaseBytes,
  });
  if (bytes.byteLength !== canonicalAdoption40Fixture.databaseBytes
    || createHash("sha256").update(bytes).digest("hex") !== canonicalAdoption40Fixture.databaseSha256) {
    throw new Error("Canonical schema-40 fixture bytes changed.");
  }
  return bytes;
}
